Module G := Selvedge.Generated.Commands.
Inductive interpretation :=
 | Observation (run : option N -> world -> json)
 | Mutation (run : option Tasks.native_call -> world -> decision).
Definition require_handler {A : Type} (value : option A) (present : value <> None) : A.
Proof. destruct value as [value|]; [exact value|exfalso; apply present; reflexivity]. Defined.

